  workVals() {
    const n = 2;
    const pick = (v, d) => (v && v !== '#') ? v : d;
    const active = (this.state && this.state.active) || 0;
    const data = [
      { name: 'Talyer Tally', sub: 'Motorshop Tally', badge: 'WEB APP · MOTORSHOP', img: 'assets/talyer-icon.png', alt: 'Talyer Tally app icon', desc: 'Every part taken, every peso counted. Job orders, parts tally per mechanic, labor presets and bill-out with automatic sukli, plus reports and offline use.', link: pick(this.props.link1, 'https://talyerv1.vercel.app/') },
      { name: 'Pin.', sub: 'Collage Editor', badge: 'ANDROID · PHOTO APP', img: 'assets/pin-icon.png', alt: 'Pin. app icon', desc: 'Turn trip photos into scrapbook collages and photo grids, with frames, cut-out stickers, 23 mood fonts, layers and high-res export.', link: pick(this.props.link2, 'https://pinv1.vercel.app/') }
    ];
    const go = (i) => this.setState({ active: ((i % n) + n) % n });
    const base = { position: 'absolute', top: '0', left: '50%', width: 'min(480px, calc(100vw - 72px))', boxSizing: 'border-box', padding: '36px', background: '#FFFFFF', border: '1px solid #E6E8EC', borderRadius: '30px', boxShadow: '0 30px 60px rgba(20,40,70,0.12)', transformOrigin: '50% 100%', transition: 'transform 0.5s cubic-bezier(0.2,0.8,0.2,1), opacity 0.5s' };
    const projects = data.map((p, i) => {
      const pos = (i - active + n) % n;
      let transform, zIndex, opacity;
      if (pos === 0) { transform = 'translateX(-50%) rotate(0deg)'; zIndex = 3; opacity = 1; }
      else if (pos === 1) { transform = 'translateX(-50%) translateX(36%) translateY(40px) rotate(7deg) scale(0.9)'; zIndex = 1; opacity = 0.55; }
      else { transform = 'translateX(-50%) translateX(-36%) translateY(30px) rotate(-7deg) scale(0.9)'; zIndex = 2; opacity = 0.55; }
      return Object.assign({}, p, {
        cardStyle: Object.assign({}, base, { transform: transform, zIndex: zIndex, opacity: opacity }),
        isSide: pos !== 0,
        label: 'Show ' + p.name,
        show: () => go(i),
        dotStyle: { width: pos === 0 ? '28px' : '10px', height: '10px', padding: '0', border: '0', borderRadius: '999px', background: pos === 0 ? '#0B0B0F' : '#C9CED6', cursor: 'pointer', transition: 'width 0.3s' }
      });
    });
    return { projects: projects, prevProject: () => go(active - 1), nextProject: () => go(active + 1) };
  }

  measure() {
    const q = (s) => document.querySelector(s);
    const card = q('.hero2 .id-card'), photo = q('.hero2 .id-photo'), name = q('.hero2 .id-name');
    const side = q('.dz-side .dz-card'), sPhoto = q('.dz-side .side-photo'), sName = q('.dz-side .side-name'), grid = q('.dz-grid');
    if (!card || !photo || !name || !side || !sPhoto || !sName || !grid) { this._m = null; return; }
    const sy = window.scrollY;
    const R = (el) => { const r = el.getBoundingClientRect(); return { x: r.left, y: r.top + sy, w: r.width, h: r.height }; };
    const rel = (inner, outer) => ({ x: inner.x - outer.x, y: inner.y - outer.y, w: inner.w, h: inner.h });
    const a = R(card), b = R(side);
    // the sidebar's resting (unstuck) top is the top of its grid
    b.y = R(grid).y;
    this._m = { a: a, b: b, ap: rel(R(photo), R(card)), bp: rel(R(sPhoto), R(side)), an: rel(R(name), R(card)), bn: rel(R(sName), R(side)), end: Math.max(1, b.y - 96) };
  }

  componentDidMount() {
    this._onScroll = () => {
      if (this._raf) return;
      this._raf = requestAnimationFrame(() => { this._raf = 0; this._tick(); });
    };
    // shrink any section that is taller than one screen so every scroll shows one full section
    this.fitSections = () => {
      const avail = (window.innerHeight - 76) * 0.8;
      document.querySelectorAll('.dz-main > section').forEach((sec) => {
        const kids = Array.from(sec.children).filter((k) => k.offsetParent !== null);
        kids.forEach((k) => { k.style.zoom = ''; });
        if (window.innerWidth <= 1180 || !kids.length) return;
        const top = kids[0].getBoundingClientRect().top;
        const bottom = kids[kids.length - 1].getBoundingClientRect().bottom;
        const h = bottom - top;
        {
          const z = Math.max(0.62, Math.min(0.92, avail / h));
          kids.forEach((k) => { k.style.zoom = String(z); });
        }
      });
    };
    this._onResize = () => { this.fitSections(); this.measure(); this._tick(); };
    this.fitSections();
    setTimeout(this.fitSections, 300);
    setTimeout(this.fitSections, 1200);
    this.measure();
    setTimeout(() => { if (window.scrollY < 40) this.measure(); this._tick(); }, 600);
    window.addEventListener('resize', this._onResize);
    this._tick = () => {
      const wide = window.innerWidth > 900 && !(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
      const mp = this._m ? Math.max(0, Math.min(1, window.scrollY / this._m.end)) : 1;
      if (mp !== this.state.morphP || wide !== this.state.morphWide) this.setState({ morphP: mp, scrollS: window.scrollY, morphWide: wide });
      const hero = document.querySelector('.hero-screen');
      const limit = hero ? hero.offsetHeight - 90 : 600;
      const dark = window.scrollY > limit;
      let active = '';
      ['work', 'apps', 'skills', 'about', 'faq'].forEach((id) => {
        const el = document.getElementById(id);
        if (el && el.getBoundingClientRect().top < 160) active = id;
      });
      if (dark !== this.state.dark || active !== this.state.navActive) {
        this.setState({ dark: dark, navActive: active });
      }
      this._ready = true;
    };
    window.addEventListener('scroll', this._onScroll, { passive: true });
    this._tick();
  }

