        trig: node('trig', [40, 110, 96, 96], { borderRadius: '48px 16px 16px 48px', cursor: 'pointer', font: 'inherit' }),
        val: node('val', [232, 118, 190, 80], { justifyContent: 'flex-start', padding: '0 16px', borderRadius: '14px' }),
