  async runWorkflow(e) {
    if (e && e.preventDefault) e.preventDefault();
    const st = this.state || {};
    if (st.cStatus === 'sending') return;
    const name = (st.cName || '').trim(), email = (st.cEmail || '').trim(), message = (st.cMsg || '').trim();
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const set = (patch) => this.setState({ wf: Object.assign({}, (this.state && this.state.wf) || {}, patch) });
    this.setState({ modalOpen: false, cStatus: 'sending', wf: { trig: 'running' } });
    await wait(400); set({ trig: 'done', val: 'running' });
    await wait(700); set({ val: 'done', iff: 'running' });
    await wait(450);
    const bad = (!name || !email || !message) ? 'Please fill in your name, email and message.' : (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? 'Please enter a valid email address.' : '');
    if (bad) { set({ iff: 'done', rej: 'error' }); this.setState({ cStatus: 'error', cError: bad + ' Click the first node to try again.' }); return; }
    set({ iff: 'done', cel: 'running' });
    try {
      const r = await fetch(this.props.contactEndpoint || '/api/contact', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: name, email: email, message: message, company: st.cTrap || '' }) });
      const data = await r.json().catch(() => ({}));
      if (!r.ok) { set({ cel: 'error' }); this.setState({ cStatus: 'error', cError: data.error || 'Could not send right now. Please email me directly.' }); return; }
      set({ cel: 'done', cli: 'running' });
      await wait(600);
      set({ cli: data.autoreply === false ? 'warn' : 'done' });
      await wait(200);
      this.setState({ cStatus: 'sent', cName: '', cEmail: '', cMsg: '' });
    } catch (err) {
      set({ cel: 'error' });
      this.setState({ cStatus: 'error', cError: 'Could not send right now (sending only works on the live site). You can email me at magbunagceljie@gmail.com.' });
    }
  }

  flowVals() {
    const st = this.state || {};
    const done = st.fDone || 0, run = st.fRun == null ? -1 : st.fRun, err = st.fErr == null ? -1 : st.fErr, warn = st.fWarn == null ? -1 : st.fWarn;
    const N = [
      ['Form submitted', 'Webhook · POST /api/contact', '#D97757', 'M13 2L4 14h7l-1 8 9-12h-7z'],
      ['Validate & filter spam', 'Required fields · honeypot check', '#8FD3FF', 'M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z M9 12l2 2 4-4'],
      ['Gmail → Celjie', 'New message notification', '#F2A9BC', 'M3 5h18v14H3z M3 6l9 7 9-7'],
      ['Gmail → You', 'Automatic thank-you reply', '#B9A2EE', 'M9 14L4 9l5-5 M4 9h11a5 5 0 0 1 5 5v6'],
      ['Done', 'I reply within 1-2 business days', '#3DD68C', 'M5 12l5 5 9-10']
    ];
    const stateOf = (i) => i === err ? 'error' : i === warn ? 'warn' : i < done ? 'done' : i === run ? 'running' : 'idle';
    const BADGE = { idle: ['Waiting', '#9A9AA3', 'rgba(255,255,255,0.05)'], running: ['Running…', '#F2A9BC', 'rgba(242,169,188,0.12)'], done: ['Success', '#3DD68C', 'rgba(61,214,140,0.12)'], warn: ['Skipped', '#FFC857', 'rgba(255,200,87,0.12)'], error: ['Failed', '#FF6B6B', 'rgba(255,107,107,0.12)'] };
    const BORDER = { idle: '#26262B', running: '#F2A9BC', done: '#2E6B4C', warn: '#8A6A1F', error: '#8A2E2E' };
    const flowNodes = N.map((n, i) => {
      const s = stateOf(i), b = BADGE[s];
      const next = i + 1 < N.length ? stateOf(i + 1) : 'idle';
      return {
        title: n[0], sub: n[1], icon: n[3], badge: b[0], hasLink: i < N.length - 1,
        linkClass: next === 'running' ? 'is-active' : (next === 'done' || next === 'warn') ? 'is-done' : '',
        boxStyle: { display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 14px', borderRadius: '16px', background: '#18181B', border: '1px solid ' + BORDER[s], opacity: s === 'idle' && done > 0 ? 0.6 : 1, animation: s === 'running' ? 'nodepulse 1.2s ease-in-out infinite' : 'none', transition: 'border-color .3s, opacity .3s' },
        iconStyle: { width: '40px', height: '40px', flexShrink: '0', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: n[2], background: 'rgba(255,255,255,0.05)', border: '1px solid ' + n[2] + '55' },
        badgeStyle: { flexShrink: '0', fontSize: '11px', fontWeight: '700', letterSpacing: '0.04em', padding: '4px 10px', borderRadius: '999px', color: b[1], background: b[2] }
      };
    });
    const status = st.cStatus || 'idle';
    const pill = status === 'sending' ? ['Running', '#F2A9BC'] : status === 'sent' ? ['Completed', '#3DD68C'] : status === 'error' ? ['Error', '#FF6B6B'] : ['Ready', '#9A9AA3'];
    return { flowNodes: flowNodes, flowPill: '● ' + pill[0], flowPillStyle: { fontSize: '12px', fontWeight: '700', color: pill[1], padding: '4px 12px', borderRadius: '999px', border: '1px solid #33333A', background: '#18181B' } };
  }

  async sendMsg(e) {
    if (e && e.preventDefault) e.preventDefault();
    const st = this.state || {};
    if (st.cStatus === 'sending') return;
    const name = (st.cName || '').trim(), email = (st.cEmail || '').trim(), message = (st.cMsg || '').trim();
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    this.setState({ cStatus: 'sending', fDone: 1, fRun: 1, fErr: -1, fWarn: -1 });
    await wait(450);
    if (!name || !email || !message) { this.setState({ cStatus: 'error', cError: 'Please fill in your name, email and message.', fErr: 1, fRun: -1 }); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { this.setState({ cStatus: 'error', cError: 'Please enter a valid email address.', fErr: 1, fRun: -1 }); return; }
    this.setState({ fDone: 2, fRun: 2 });
    try {
      const r = await fetch(this.props.contactEndpoint || '/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: name, email: email, message: message, company: st.cTrap || '' })
      });
      const data = await r.json().catch(() => ({}));
      if (r.ok) {
        this.setState({ fDone: 3, fRun: 3 });
        await wait(550);
        if (data.autoreply === false) this.setState({ fWarn: 3, fDone: 4, fRun: 4 });
        else this.setState({ fDone: 4, fRun: 4 });
        await wait(400);
        this.setState({ cStatus: 'sent', cName: '', cEmail: '', cMsg: '', fDone: 5, fRun: -1 });
      } else {
        this.setState({ cStatus: 'error', cError: data.error || 'Could not send right now. Please email me directly.', fErr: 2, fRun: -1 });
      }
    } catch (err) {
      this.setState({ cStatus: 'error', cError: 'Could not send right now. Please email me at magbunagceljie@gmail.com.', fErr: 2, fRun: -1 });
    }
  }

