    if (!on) return out;
    const e = p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;
    const L = (x, y) => x + (y - x) * e;
    const hx = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
