    out.clonePhotoStyle = { position: 'absolute', left: L(m.ap.x, m.bp.x) + 'px', top: L(m.ap.y, m.bp.y) + 'px', width: L(m.ap.w, m.bp.w) + 'px', height: L(m.ap.h, m.bp.h) + 'px', borderRadius: L(18, m.bp.w / 2) + 'px', overflow: 'hidden', background: 'linear-gradient(180deg, #F8E6EA, #EBB7C5)', boxShadow: '0 0 0 ' + (5 * e).toFixed(1) + 'px #A8322D' };
    out.cloneNameStyle = { position: 'absolute', left: L(m.an.x, m.bn.x) + 'px', top: L(m.an.y, m.bn.y) + 'px', whiteSpace: 'nowrap', fontFamily: "'Jost', 'Zen Kaku Gothic New', sans-serif", fontSize: L(22, 28) + 'px', fontWeight: e > 0.5 ? '800' : '600', fontStyle: e > 0.5 ? 'italic' : 'normal', lineHeight: '1.1', letterSpacing: L(-0.01, -0.02) + 'em', color: mix('#0B0B0F', '#FFFFFF') };
