      projects: work.projects,
      prevProject: work.prevProject,
      nextProject: work.nextProject,
      skillTabs: sk.skillTabs,
      skillTiles: sk.skillTiles,
      selSkill: sk.selSkill,
      selIconStyle: sk.selIconStyle,
      selLevelStyle: sk.selLevelStyle
